#define FOCAL 1.5

float hash( float n )
{
    return fract(sin(n)*43758.5453);
}

vec3 hash3( float n )
{
    return fract(sin(vec3(n,n+1.0,n+2.0))*vec3(43758.5453123,22578.1459123,19642.3490423));
}

vec3 random3f( vec3 p )
{
#if 1
	return texture( iChannel0, (p.xy + vec2(3.0,1.0)*p.z+0.5)/256.0, -100.0 ).xyz;
#else
    return fract(sin(vec3( dot(p,vec3(1.0,57.0,113.0)), 
                           dot(p,vec3(57.0,113.0,1.0)),
                           dot(p,vec3(113.0,1.0,57.0))))*43758.5453);
#endif	
}

vec3 voronoi( in vec3 x )
{
    vec3 p = floor( x );
    vec3 f = fract( x );

	float id = 0.0;
    vec2 res = vec2( 100.0 );
    for( int k=-1; k<=1; k++ )
    for( int j=-1; j<=1; j++ )
    for( int i=-1; i<=1; i++ )
    {
        vec3 b = vec3( float(i), float(j), float(k) );
        vec3 r = vec3( b ) - f + random3f( p + b );
        float d = dot( r, r );

        if( d < res.x )
        {
			id = dot( p+b, vec3(1.0,57.0,113.0 ) );
            res = vec2( d, res.x );			
        }
        else if( d < res.y )
        {
            res.y = d;
        }
    }
    return vec3( sqrt( res ), abs(id) );
}

vec3 map( in vec3 p )
{
	vec3 q = vec3( p.x, p.y, p.z  );
	float d1 = length(q) - 1.0;

    //return vec3( length(q) - 1.0 );
	float h = 0.5+0.5*clamp(1.0-p.y,0.0,1.0);
    vec3 v = voronoi(2.0*p);
	float f = clamp( 3.5*(v.y-v.x), 0.0, 1.0 );
	d1 -= 0.2*f*h;
    return vec3( 0.5*d1, mix(1.0,f,h), v.z );

}

vec3 calcNormal( in vec3 pos )
{
	vec3 eps = vec3( 0.01, 0.00, 0.0 );
	vec3 nor = vec3(
	    map(pos+eps.xyy).x - map(pos-eps.xyy).x,
	    map(pos+eps.yxy).x - map(pos-eps.yxy).x,
	    map(pos+eps.yyx).x - map(pos-eps.yyx).x );
	return normalize(nor);

    //map(pos+eps.xyy).x - map(pos-eps.xyy).x,

    //map(pos+vec3(0.01, 0.,0.).x) - map(pos-vec3(0.01, 0.,0.).x
}

vec3 intersect( in vec3 ro, in vec3 rd )
{
	float maxd = 20.0;
	float precis = 0.001;
    float h = 1.0;
    float t = 0.0;
    float m = -1.0;
	float o = 0.0;
    for( int i=0; i<32; i++ )
    {
        if( h<(precis*t)||t>maxd ) break;
        t += h;
	    vec3 res = map( ro+rd*t );
        h = res.x;
		o = res.y;
	    m = res.z;
    }

    if( t>maxd ) m=-1.0;
    return vec3( t, o, m );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 q = fragCoord.xy/iResolution.xy;
	vec2 p = -1.0+2.0*q;
	p.x *= iResolution.x/iResolution.y;

	// camera	
	vec3 ro =  vec3( sin(iTime*0.2)*4.0, 1. ,cos(iTime*0.2)*4.0 );
	vec3 ta =  vec3( 0.0,0.0,0.0 );

	float roll = -0.15*sin(0.5*iTime);

	// camera tx
	vec3 cw = normalize( ta-ro );
	vec3 cp = vec3( sin(roll), cos(roll),0.0 );
	vec3 cu = normalize( cross(cw,cp) );
	//vec3 cv = normalize( cross(cu,cw) );
	vec3 rd = normalize( p.x*cu + p.y*cp + cw*FOCAL );

	// render
    vec3 col = vec3(0.0);
	vec3 nor = vec3(0.);
	// raymarch
    vec3 tmat = intersect(ro,rd);
    col = vec3(tmat.x*0.1);
    if (tmat.z > -0.5){
        col = vec3(tmat.x*0.1);
        nor = calcNormal(ro+rd*tmat.x);
    }

    vec3 colN = vec3(-nor.y, -nor.y*-nor.y*0.5, nor.y );
    col = col + colN*0.5;
    fragColor = vec4( col,1.0 );
}
